allowed_documents = {"public-lesson": "A public lesson about vectors."}
def read_document(document_id):
    if document_id not in allowed_documents:
        raise PermissionError("Document is outside the permitted collection")
    return allowed_documents[document_id]
proposals = ["public-lesson", "../../private/secrets.txt"]
for proposal in proposals:
    try:
        print(read_document(proposal))
    except PermissionError:
        print("Blocked by application permissions")
